{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C40"],
      "claim": "Viramidine, a full ribofuranosyl nucleoside with a nitrogen-rich heterocycle, has 66.1% oral bioavailability in humans, directly supporting that the query's ribose-containing nucleoside scaffold can achieve F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C61"],
      "claim": "Didanosine, a purine nucleoside analog, has approximately 40% oral bioavailability in humans, showing that even acid-labile purine nucleosides meet the F>=20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Zalcitabine, a dideoxycytidine nucleoside, has mean oral bioavailability of 88% in patients, demonstrating that small polar nucleoside analogs can be well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Zidovudine, a modified thymidine nucleoside, has about 60% oral bioavailability in patients, supporting high F for nucleoside analogs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Didanosine under fed conditions at 50 mg/m2 had median F of 0.19, a below-threshold value; this is tied to the acid-labile dideoxy sugar and food effects, not directly to the full ribose query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a purine ribonucleoside (xanthosine). The most transferable evidence includes a full-ribose nucleoside with 66% F (viramidine) and purine nucleoside analogs with F around 40-88% (didanosine, zalcitabine, zidovudine), all supporting F>=20%. The only below-threshold values come from fed/high-dose didanosine, an acid-labile dideoxy analog, and are not sufficient to predict low. Therefore predict high.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for xanthosine itself.",
    "Potential first-pass cleavage by purine nucleoside phosphorylase is not directly represented in the retrieved evidence.",
    "Didanosine's low-F records reflect its dideoxy sugar and food effects, limiting direct extrapolation to the full ribose query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

